  var searchDraft=draft;draft=new DeckDocument{ClassId="WARRIOR",PoolId=pool.Id};SyncDeckControls();RefreshDeck();searchBox.Text="火球";Check(filteredCards.Any(c=>c.Id==fire.Id),"Search finds Mage card while editing Warrior deck");int unchanged=draft.Count;AddCard(fire);Check(draft.Count==unchanged&&!draft.Cards.ContainsKey(fire.Id),"Search visibility never permits adding foreign profession card");searchBox.Text="火球 伤害";Check(filteredCards.Any(c=>c.Id==fire.Id),"Multiple search terms match name and effect");searchBox.Text="ｖａｎ＿ｃｓ２＿０２９";Check(filteredCards.Count==1&&filteredCards[0].Id==fire.Id,"Fullwidth and case-insensitive card ID search");costPicker.SelectedItem=((Choice[])costPicker.ItemsSource).First(c=>c.Key=="0");Check(filteredCards.Count==0&&collectionRows.Children.Count==1,"Empty result explains active filters");costPicker.SelectedIndex=0;searchBox.Text="火球";ApplyTheme(true,true);ApplyMode(true);ShowPage("deck");Render(Path.Combine(folder,"65-deck-search-cross-class.png"));searchBox.Text="";Check(filteredCards.All(c=>c.CardClass=="WARRIOR"||c.CardClass=="NEUTRAL"),"Clearing search restores profession collection");draft=searchDraft;SyncDeckControls();RefreshDeck();
